/bin/zsh -lc "python3 - <<'PY'
from time import perf_counter
import cadence
bounds = \"2060-01-01T00:00Z\", \"2060-01-02T00:00Z\"
for unit, holiday, holidays in [
    (\"hour\", \"keep\", []), (\"minute\", \"keep\", []), (\"minute\", \"skip\", [\"2050-01-01\"]), (\"minute\", \"skip\", [\"2060-01-01\"])
]:
    plan = {\"timezone\":\"Europe/Berlin\", \"holidays\": holidays, \"rules\":[
        {\"id\":f\"r{i}\", \"rule\":f\"every {unit} for 1m from 1970-01-01T00:00\", \"holiday\":holiday}
        for i in range(200)
    ]}
    for query in (cadence.occurrences, cadence.agenda):
        start = perf_counter()
        rows = query(plan, *bounds)
        elapsed = perf_counter() - start
        expected = 24 if unit == \"hour\" else 60 if holidays == [\"2060-01-01\"] else 1440
        assert len(rows) == expected * (200 if query == cadence.occurrences else 1)
        print(f\"{query.__name__} · {unit}/{holiday} · {len(rows)} rows · {elapsed:.3f}s\")
plan = {\"timezone\":\"UTC\", \"holidays\":[\"1970-01-01..2059-12-31\"], \"rules\":[
    {\"id\":\"once\", \"rule\":\"every minute for 1m from 1970-01-01T00:00 times 2\", \"holiday\":\"skip\"}
]}
start = perf_counter()
rows = cadence.occurrences(plan, *bounds)
assert [x[\"key\"] for x in rows] == [\"2060-01-01T00:00Z\",\"2060-01-01T00:01Z\"]
print(f\"Counted minute rule skipping a 90-year holiday · {perf_counter()-start:.3f}s\")
PY"

